const lhr = $json.data && $json.data.categories ? $json.data : $json;
const cats = (lhr && lhr.categories) || {};
const audits = (lhr && lhr.audits) || {};
const orig = $('Loop Over Items').item.json;
const to100 = c => (c && typeof c.score==='number' ? Math.round(c.score*100) : '');
const a = id => audits[id] || {};
const s = ms => (typeof ms==='number' ? +(ms/1000).toFixed(2) : '');
if (lhr.runtimeError && !(cats.performance && typeof cats.performance.score==='number')) {
  return { json: { ...orig, perf_score:'',seo_score:'',accessibility_score:'',best_practices_score:'',lcp_s:'',tbt_ms:'',cls:'',ttfb_ms:'',potential_speedup_s:'',top_opportunities:'',
    signal: `Website failed to load in test: ${lhr.runtimeError.message}`, audit_status: lhr.runtimeError.code||'runtimeError' } };
}
const LABELS={'render-blocking-resources':'remove render-blocking scripts/CSS','uses-responsive-images':'properly size images','offscreen-images':'lazy-load offscreen images','unminified-css':'minify CSS','unminified-javascript':'minify JS','unused-css-rules':'remove unused CSS','unused-javascript':'remove unused JS','uses-optimized-images':'compress images','modern-image-formats':'serve next-gen images (WebP/AVIF)','uses-text-compression':'enable text compression','uses-long-cache-ttl':'set cache lifetimes','server-response-time':'speed up server response','redirects':'avoid landing-page redirects','efficient-animated-content':'replace GIFs with video'};
const opps=Object.entries(audits).map(([id,x])=>({id,ms:x.details&&typeof x.details.overallSavingsMs==='number'?x.details.overallSavingsMs:0})).filter(o=>o.ms>=150).sort((x,y)=>y.ms-x.ms);
const top=opps.slice(0,4).map(o=>`${LABELS[o.id]||o.id} (~${(o.ms/1000).toFixed(1)}s)`);
const perf=to100(cats.performance),seo=to100(cats.seo),a11y=to100(cats.accessibility);
const lcp=s(a('largest-contentful-paint').numericValue),tbt=a('total-blocking-time').numericValue,cls=a('cumulative-layout-shift').numericValue;
const p=[];
if(perf!=='')p.push(`Page speed ${perf}/100 (${perf>=90?'good':perf>=50?'needs work':'poor'})`);
if(lcp!==''&&lcp>2.5)p.push(`main content loads in ${lcp}s (Google flags >2.5s)`);
if(top.length)p.push(`Quick wins: ${top.slice(0,3).join(', ')}`);
if(seo!==''&&seo<90)p.push(`SEO ${seo}/100`);
if(a11y!==''&&a11y<90)p.push(`Accessibility ${a11y}/100 (ADA risk)`);
return { json: { ...orig, perf_score:perf,seo_score:seo,accessibility_score:a11y,best_practices_score:to100(cats['best-practices']),
  lcp_s:lcp, tbt_ms:typeof tbt==='number'?Math.round(tbt):'', cls:typeof cls==='number'?+cls.toFixed(3):'', ttfb_ms:typeof a('server-response-time').numericValue==='number'?Math.round(a('server-response-time').numericValue):'',
  potential_speedup_s:+(opps.reduce((t,o)=>t+o.ms,0)/1000).toFixed(1), top_opportunities:top.join(' | '),
  signal:p.join('. ')+(p.length?'.':''), audit_status:'ok' } };
